"""Publish generated bytes or cached file payloads without retaining texture RAM."""
import filecmp,os,shutil,uuid
from pathlib import Path

def publish(target,content):
    target=Path(target)
    if isinstance(content,Path):
        if target.exists() and os.path.samefile(target,content):return False
    elif target.exists() and target.read_bytes()==content:return False
    target.parent.mkdir(parents=True,exist_ok=True)
    temporary=target.with_name(target.name+'.'+uuid.uuid4().hex+'.tmp')
    try:
        if isinstance(content,Path):
            try:os.link(content,temporary)
            except OSError:
                if target.is_file() and filecmp.cmp(target,content,shallow=False):return False
                shutil.copyfile(content,temporary)
        else:temporary.write_bytes(content)
        temporary.replace(target)
    finally:temporary.unlink(missing_ok=True)
    return True
